//! The transient sample library (generated by tools/gen-translib.py),
//! embedded in the plugin. Faust reads it through `tr_read` (see lib.rs).

include!("translib_index.rs");

static DATA: &[u8] = include_bytes!("translib.bin");

#[inline(always)]
fn frame(i: usize) -> f32 {
    let i = i * 4;
    f32::from_le_bytes([DATA[i], DATA[i + 1], DATA[i + 2], DATA[i + 3]])
}

/// Sample `k` at fractional position `pos` (linear interpolation); silent
/// for an unknown sample or a position outside it.
#[inline(always)]
pub fn read(k: i32, pos: f32) -> f32 {
    let Some(&len) = usize::try_from(k).ok().and_then(|k| LENS.get(k)) else {
        return 0.0;
    };
    if pos.is_nan() || pos < 0.0 || pos >= (len - 1) as f32 {
        return 0.0;
    }
    let start = STARTS[k as usize] as usize;
    let i = pos as usize;
    let frac = pos - i as f32;
    let (a, b) = (frame(start + i), frame(start + i + 1));
    a + (b - a) * frac
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn library_is_present_and_sane() {
        let total: u32 = LENS.iter().sum();
        assert_eq!(DATA.len(), total as usize * 4);
        for k in 0..LENS.len() as i32 {
            let peak = (0..LENS[k as usize] - 1).map(|i| read(k, i as f32).abs()).fold(0.0, f32::max);
            assert!(peak > 0.8 && peak <= 1.0, "sample {k} peak {peak}");
        }
        assert_eq!(read(-1, 0.0), 0.0);
        assert_eq!(read(LENS.len() as i32, 0.0), 0.0);
        assert_eq!(read(0, -1.0), 0.0);
        assert_eq!(read(0, f32::NAN), 0.0);
        assert_eq!(read(0, 1e9), 0.0);
    }
}
